import React, { useMemo, useState } from "react";
import Navbar from "../components/Navbar";
import MapComponent from "../components/MapComponent";
import { CAMPUS_LOCATIONS } from "../constants/AppConstants";
import "./MapPage.css";

const CATEGORIES = ["All", ...new Set(CAMPUS_LOCATIONS.map((l) => l.category))];

export default function MapPage() {
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState("All");
  const [selectedId, setSelectedId] = useState(CAMPUS_LOCATIONS[0].id);

  const filtered = useMemo(() => {
    return CAMPUS_LOCATIONS.filter((l) => {
      const matchesQuery = l.name.toLowerCase().includes(query.toLowerCase());
      const matchesCategory = category === "All" || l.category === category;
      return matchesQuery && matchesCategory;
    });
  }, [query, category]);

  const selected = CAMPUS_LOCATIONS.find((l) => l.id === selectedId);

  return (
    <div>
      <Navbar />
      <div className="page-shell">
        <h3 className="section-title">Campus Map</h3>

        <div className="map-toolbar">
          <input
            className="field"
            placeholder="Search lecture halls, library, offices ..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
          <select value={category} onChange={(e) => setCategory(e.target.value)}>
            {CATEGORIES.map((c) => (
              <option key={c} value={c}>{c}</option>
            ))}
          </select>
        </div>

        <div className="map-layout">
          <div>
            <MapComponent locations={filtered} selectedId={selectedId} onSelect={setSelectedId} />
            {selected && (
              <div className="map-detail">
                <h4>{selected.name}</h4>
                <p>{selected.info}</p>
              </div>
            )}
          </div>

          <div className="map-list">
            {filtered.length === 0 ? (
              <div style={{ padding: 20, color: "var(--text-faint)" }}>No locations match your search.</div>
            ) : (
              filtered.map((loc) => (
                <button
                  key={loc.id}
                  className={`map-list-item ${loc.id === selectedId ? "active" : ""}`}
                  onClick={() => setSelectedId(loc.id)}
                >
                  <div className="map-list-name">{loc.name}</div>
                  <div className="map-list-category">{loc.category}</div>
                </button>
              ))
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
